package com.keplerslicer.app;
import android.content.Context;import android.content.SharedPreferences;import java.io.*;import java.nio.ByteBuffer;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.json.JSONObject;
public final class ProcessOverridesStoreTest {
 private static int assertions;private interface Run{void call()throws Exception;}private static void check(boolean value,String message){assertions++;if(!value)throw new AssertionError(message);}private static void rejects(Run run,String message)throws Exception{try{run.call();throw new AssertionError(message);}catch(IOException expected){assertions++;}}
 private static String digest(String... values)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");for(String s:values){byte[] b=s.getBytes(StandardCharsets.UTF_8);d.update(ByteBuffer.allocate(4).putInt(b.length).array());d.update(b);}StringBuilder out=new StringBuilder();for(byte b:d.digest())out.append(String.format("%02x",b&255));return out.toString();}
 private static String[] fields(){return new String[]{"revision","VP","Printer","VP/machine/p.json","VQ","Process","VQ/process/q.json","VF","Filament","VF/filament/f.json"};}
 private static String[] append(String[] values,String... more){String[] out=java.util.Arrays.copyOf(values,values.length+more.length);System.arraycopy(more,0,out,values.length,more.length);return out;}
 public static void main(String[] args)throws Exception{
  Context c=new Context(new File(args[0]),new File(args[0]));SharedPreferences pref=c.getSharedPreferences("kepler_process_overrides_v1",0);String payload="{\"layer_height\":0.19}";String legacy=digest(fields()),prior=digest(append(fields(),"profile-a")),full=digest(append(fields(),"profile-a","objects-a","mixed-temperatures:false"));
  ProcessOverridesStore.Identity identity=ProcessOverridesStore.Identity.capture(c);check(identity.legacyFingerprint.equals(legacy),"legacy digest matches old 10-field implementation");check(identity.priorProfileFingerprint.equals(prior),"old 11-field digest matches");check(identity.fingerprint.equals(full),"full 13-field digest matches (object settings + mixed-temperature flag)");
  for(String id:new String[]{legacy,prior,full}){pref.edit().putString("identity",id).putString("values",payload).commit();ProcessOverridesStore.Snapshot s=ProcessOverridesStore.snapshotForSlice(c);check(new JSONObject(s.overrides).getDouble("layer_height")==0.19,"old payload retained");check(pref.getString("identity","").equals(legacy),"old id uses 10-field binding");}
  pref.edit().putString("identity",prior).putString("values",payload).commit();c.failNextCommit("kepler_process_overrides_v1");rejects(()->ProcessOverridesStore.snapshotForSlice(c),"failed migration reports failure");check(pref.getString("identity","").equals(prior),"failed migration restores prior id");check(pref.getString("values","").equals(payload),"failed migration preserves payload");ProcessOverridesStore.snapshotForSlice(c);
  ProcessOverridesStore.Identity beforeEdit=ProcessOverridesStore.Identity.capture(c);String initial=ProcessOverridesStore.currentResultFingerprint(c);SettingsState.profileFingerprint="profile-b";ProcessOverridesStore.Snapshot changed=ProcessOverridesStore.snapshotForSlice(c);check(new JSONObject(changed.overrides).getDouble("layer_height")==0.19,"profile edit retains legacy");check(!initial.equals(ProcessOverridesStore.currentResultFingerprint(c)),"profile edit invalidates result");
  rejects(()->ProcessOverridesStore.save(c,beforeEdit,"{}"),"stale editor snapshot is rejected");check(new JSONObject(ProcessOverridesStore.snapshotForSlice(c).overrides).getDouble("layer_height")==0.19,"stale save leaves old overrides intact");ProcessOverridesStore.Identity latest=ProcessOverridesStore.Identity.capture(c);ProcessOverridesStore.save(c,latest,payload);check(pref.getString("identity","").equals(legacy),"new saves use the system triple digest");
  String afterProfile=ProcessOverridesStore.currentResultFingerprint(c);ObjectSettingsStore.fingerprint="objects-b";check(new JSONObject(ProcessOverridesStore.snapshotForSlice(c).overrides).getDouble("layer_height")==0.19,"object edit retains legacy");check(!afterProfile.equals(ProcessOverridesStore.currentResultFingerprint(c)),"object edit invalidates result");
  ObjectSettingsStore.file="model-other.stl";rejects(()->ProcessOverridesStore.currentResultFingerprint(c),"different model scope rejected");ObjectSettingsStore.file="model-one.stl";ObjectSettingsStore.plate=2;rejects(()->ProcessOverridesStore.currentResultFingerprint(c),"different plate scope rejected");ObjectSettingsStore.plate=-1;
  SettingsState.mismatch=true;rejects(()->ProcessOverridesStore.snapshotForSlice(c),"overlay identity mismatch rejected");SettingsState.mismatch=false;
  PrintProfileCatalog.process=new PrintProfileCatalog.Profile("VQ","Other","VQ/process/other.json");check(ProcessOverridesStore.snapshotForSlice(c).overrides.equals("{}"),"different system triple cannot apply legacy values");check(pref.getString("identity","").equals(legacy),"mismatched read does not destroy old record");
  ProcessOverridesStore.changeSelection(c,false,()->{});check(pref.getString("identity","").equals(legacy),"same-base selection preserves legacy");ProcessOverridesStore.changeSelection(c,true,()->{});check(pref.getAll().isEmpty(),"different-base selection clears legacy");
  System.out.println("Process overrides: "+assertions+" assertions passed");
 }
}
